function mockList(){ const box=$('#mockResults'), cnt=$('#mockCount'); if(!box) return;
  const q=(csaState.mockQ||'').trim().toLowerCase(); const toks=q.split(/[^a-z0-9]+/).filter(t=>t.length>1);
  let list=CSA_MOCKCALLS.map((e,i)=>({e,i})).filter(({e})=>(csaState.mockCat==='all'||e.cat===csaState.mockCat));
  if(toks.length){ list=list.filter(({e})=>{ const hay=(e.title+' '+e.summary+' '+(e.talkingPoints||[]).join(' ')+' '+(e.cheatSheet||[]).join(' ')+' '+(e.discoveryQs||[]).join(' ')).toLowerCase(); return toks.every(t=>hay.includes(t)); }); }
  if(cnt) cnt.textContent=`${list.length} mock call${list.length===1?'':'s'}`;
  if(!list.length){ box.innerHTML=`<div class="csaResHint">No mock calls match &mdash; try <b>quality</b>, <b>ROI</b>, <b>scope</b>, or <b>reporting</b>.</div>`; return; }
  box.innerHTML=`<div class="kbGrid">${list.map(({e,i})=>scenCard(e,i)).join('')}</div>`;
  box.querySelectorAll('.scenOpen').forEach(b=>b.onclick=()=>{ csaState.mockSel=+b.dataset.i; renderAcadMock(); const st=$('#acadStage'); if(st) st.scrollIntoView({behavior:'smooth',block:'start'}); });
}
// --- client management playbook (post-onboarding scenarios) ---
function objCard(o,i){
  return `<button class="kbCard objCard objOpen" data-i="${i}"><div class="kbCardHd"><span class="kbBadge kb-difficult">&#128737; ${esc(o.category||'Client mgmt')}</span></div>
    <div class="kbTitle">${esc(o.title)}</div>
    ${o.clientSays?`<div class="objSaysCard">&ldquo;${esc(o.clientSays)}&rdquo;</div>`:''}
    <div class="kbSummary">${esc(o.concern||'')}</div>
    <span class="wizghost objMore">Open playbook &rarr;</span></button>`;
}
function objDetail(o){
  const list=a=>`<ul>${(a||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`;
  const fw=o.framework?`<div class="fwRow"><b>${esc(o.framework.name)}</b> — ${esc(o.framework.desc)}</div>`:'<p>—</p>';
  const blocks=[
    ['&#128336; When it typically occurs',`<p>${esc(o.whenOccurs)}</p>`],
    ['&#128173; What the client is really worried about',`<p>${esc(o.concern)}</p>`],
    ['&#128269; Discovery questions',list(o.discoveryQs)],
    ['&#129504; Recommended communication framework',fw],
    ['&#128222; Sample call script',scriptBox(o.callScript)],
    ['&#9993;&#65039; Sample email &amp; chat',promptBox(o.emailSample)+`<div class="recipeK" style="margin-top:10px">Chat / Slack reply</div>`+promptBox(o.chatSample)],
    ['&#9989; Best practices',list(o.bestPractices)],
    ['&#10060; Common mistakes to avoid',list(o.mistakes)],
    ['&#128260; Follow-up actions to rebuild trust &amp; reinforce value',list(o.followUps)],
  ];
  return `<div class="wizpanel"><span class="kbBadge kb-difficult">&#128737; ${esc(o.category||'Client management')}</span>
    <div class="wizh" style="margin:8px 0 0">${esc(o.title)}</div>
    ${o.clientSays?`<div class="simBubble" style="margin-top:10px"><span class="simWho">Client</span><p>&ldquo;${esc(o.clientSays)}&rdquo;</p></div>`:''}
    <div class="delivgrid" style="margin-top:12px">${blocks.map(b=>`<div class="delivblock"><div class="delivh">${b[0]}</div><div class="delivb">${b[1]}</div></div>`).join('')}</div></div>`;
}
function renderAcadObj(){ const s=$('#acadStage'); if(!s) return;
  if(csaState.objSel!=null && CSA_OBJECTIONS[csaState.objSel]){
    s.innerHTML=`<div class="wizrow" style="margin:6px 0 12px"><button class="wizghost" id="objBack">&larr; All scenarios</button></div>${objDetail(CSA_OBJECTIONS[csaState.objSel])}`;
    $('#objBack').onclick=()=>{ csaState.objSel=null; renderAcadObj(); const st=$('#acadStage'); if(st) st.scrollIntoView({behavior:'smooth',block:'start'}); }; bindCopy(); return;
  }
  s.innerHTML=`<p class="wizsub" style="margin:2px 0 8px">Handle the conversations that come up once a client is <b>live on MAVIS</b> — value gaps, delays, out-of-scope asks, scope creep, low adoption, ROI doubts, accuracy &amp; privacy questions, and retention risk. Each scenario gives you the concern beneath the surface, discovery questions, a framework, ready-to-use call/email/chat responses, and follow-up actions to rebuild trust.</p><input id="objSearch" class="ecoSearch" placeholder="Search scenarios — value, delays, scope creep, adoption, ROI, accuracy, privacy, retention..." autocomplete="off" value="${esc(csaState.objQ||'')}"><div class="ccount" id="objCount"></div><div id="objResults"></div>`;
  const os=$('#objSearch'); if(os) os.oninput=()=>{ csaState.objQ=os.value; objList(); };
  objList();
}
function objList(){ const box=$('#objResults'), cnt=$('#objCount'); if(!box) return;
  const q=(csaState.objQ||'').trim().toLowerCase(); const toks=q.split(/[^a-z0-9]+/).filter(t=>t.length>1);
  let list=CSA_OBJECTIONS.map((o,i)=>({o,i}));
  if(toks.length){ list=list.filter(({o})=>{ const hay=(o.title+' '+o.category+' '+(o.clientSays||'')+' '+(o.concern||'')+' '+(o.whenOccurs||'')+' '+(o.bestPractices||[]).join(' ')+' '+(o.discoveryQs||[]).join(' ')).toLowerCase(); return toks.every(t=>hay.includes(t)); }); }
  if(cnt) cnt.textContent=`${list.length} scenario${list.length===1?'':'s'}`;
  if(!list.length){ box.innerHTML=`<div class="csaResHint">No scenarios match &mdash; try <b>value</b>, <b>adoption</b>, <b>ROI</b>, <b>accuracy</b>, or <b>retention</b>.</div>`; return; }
  box.innerHTML=`<div class="kbGrid">${list.map(({o,i})=>objCard(o,i)).join('')}</div>`;
  box.querySelectorAll('.objOpen').forEach(b=>b.onclick=()=>{ csaState.objSel=+b.dataset.i; renderAcadObj(); const st=$('#acadStage'); if(st) st.scrollIntoView({behavior:'smooth',block:'start'}); });
}
// --- conversation simulator ---
function simBand(v){ return v>=80?'good':v>=55?'mid':'low'; }
function simReact(fb){ if(!fb||fb.tooShort) return 'down'; const s=fb.scores||{}; const warmth=((s.rapport||0)+(s.empathy||0)+(s.listening||0))/3; return (fb.overall>=57 && warmth>=48)?'up':'down'; }
function simClientLine(sim,idx){ if(idx===0) return sim.turns[0].c; const prev=csaState.simLog[idx-1]; const tier=(prev&&prev.tier)||'down'; const t=sim.turns[idx]; return (tier==='up'&&t.up)?t.up:t.c; }
// ── voice: text-to-speech + speech-to-text (browser-native, no backend) ──
var simRecog=null, simListening=false, simCallStart=0, simTimerInt=null, simVoice=null, simVoicePool=[], simVoiceOverride=null;
function simRankVoices(){ try{ const ss=window.speechSynthesis; if(!ss) return []; let vs=(ss.getVoices()||[]).filter(v=>/^en/i.test(v.lang)); const sc=v=>{ let s=0; const n=(v.name||''); if(/en[-_]US/i.test(v.lang)) s+=40; else if(/en[-_](GB|AU|CA|IE)/i.test(v.lang)) s+=18; if(/neural/i.test(n)) s+=70; if(/natural/i.test(n)) s+=65; if(/online/i.test(n)) s+=55; if(/google/i.test(n)) s+=45; if(/premium|enhanced|siri/i.test(n)) s+=35; if(/microsoft/i.test(n)) s+=12; if(v.localService===false) s+=12; return s; }; return vs.map(v=>({v,s:sc(v)})).sort((a,b)=>b.s-a.s).map(o=>o.v); }catch(e){ return []; } }
function simPickVoice(){ try{ simVoicePool=simRankVoices(); if(!simVoiceOverride){ try{ const sv=localStorage.getItem('csaSimVoice'); if(sv&&sv!=='__auto'){ const m=simVoicePool.find(v=>v.name===sv); if(m) simVoiceOverride=m; } }catch(e){} } simVoice=simVoiceOverride||simVoicePool[0]||null; }catch(e){} }
try{ if(window.speechSynthesis){ window.speechSynthesis.onvoiceschanged=simPickVoice; simPickVoice(); } }catch(e){}
function simVoiceGender(nm){ nm=(nm||'').toLowerCase(); if(/aria|jenny|jessa|michelle|ana|zira|samantha|susan|karen|female|linda|catherine|hazel|fiona|moira|tessa|victoria|allison|ava|joanna|salli|kimberly|kendra|ivy|emma|amy|sonia|libby|natasha|clara/.test(nm)) return 'f'; if(/guy|christopher|david|mark|male|daniel|alex|george|james|ryan|eric|thomas|fred|oliver|arthur|brian|matthew|justin|joey|william|liam|ronald|tony|aaron/.test(nm)) return 'm'; return ''; }
function simPersonaGender(sim){ const t=(((sim&&sim.persona)||'')+' '+((sim&&sim.situation)||'')); if(/\bshe\b|\bher\b|\bhers\b|\bmrs\.?|\bms\.?\b/i.test(t)) return 'f'; if(/\bhe\b|\bhis\b|\bhim\b|\bmr\.?\b/i.test(t)) return 'm'; return ''; }
function simScenarioVoice(){ if(simVoiceOverride) return simVoiceOverride; if(!simVoicePool.length) simPickVoice(); if(!simVoicePool.length) return null; const sim=(csaState.simSel!=null)?CSA_SIMS[csaState.simSel]:null; const want=simPersonaGender(sim); let pool=simVoicePool; if(want){ const g=simVoicePool.filter(v=>simVoiceGender(v.name)===want); if(g.length) pool=g; } const idx=((csaState.simSel!=null?csaState.simSel:0)%pool.length); return pool[idx]||simVoicePool[0]||null; }
function simProsody(){ const sim=(csaState.simSel!=null)?CSA_SIMS[csaState.simSel]:null; const t=((((sim&&sim.persona)||'')+' '+((sim&&sim.category)||'')+' '+((sim&&sim.situation)||''))).toLowerCase(); let rate=0.98, pitch=1; if(/exec|busy|short on time|rushed|behind|no time|in a hurry/.test(t)){ rate=1.08; pitch=0.98; } else if(/friendly|warm|talkative|chatty|easygoing|cheerful/.test(t)){ rate=0.97; pitch=1.05; } else if(/skeptic|frustrat|annoy|upset|angry|dispute|unhappy|irritat/.test(t)){ rate=0.99; pitch=0.93; } else if(/reserved|quiet|analytic|guarded|cautious/.test(t)){ rate=0.95; pitch=0.99; } return {rate:rate,pitch:pitch}; }
function simSpeak(text){ try{ const ss=window.speechSynthesis; if(!ss||!text) return; ss.cancel(); if(!simVoicePool.length) simPickVoice(); const v=simScenarioVoice(); const p=simProsody(); const u=new SpeechSynthesisUtterance((''+text).replace(/[“”]/g,'"').replace(/[‘’]/g,"'")); u.rate=p.rate; u.pitch=p.pitch; if(v){ u.voice=v; u.lang=v.lang||'en-US'; } ss.speak(u); }catch(e){} }
function simSupportsMic(){ return !!(window.SpeechRecognition||window.webkitSpeechRecognition); }
function simMicToggle(){ const SR=window.SpeechRecognition||window.webkitSpeechRecognition; if(!SR) return;
  if(simListening){ try{ if(simRecog) simRecog.stop(); }catch(e){} return; }
  try{ if(window.speechSynthesis) window.speechSynthesis.cancel(); }catch(e){}
  simRecog=new SR(); simRecog.lang='en-US'; simRecog.interimResults=true; simRecog.continuous=true;
  let base=csaState.simText||'';
  simRecog.onresult=(e)=>{ let interim='',final=''; for(let i=e.resultIndex;i<e.results.length;i++){ const r=e.results[i]; if(r.isFinal) final+=r[0].transcript; else interim+=r[0].transcript; } if(final) base=(base?base+' ':'')+final.trim(); csaState.simText=(base+(interim?' '+interim:'')).trim(); const ta=$('#simInput'); if(ta) ta.value=csaState.simText; };
  const done=()=>{ simListening=false; const mb=$('#simMic'); if(mb){ mb.classList.remove('rec'); mb.innerHTML='&#127908; Speak your answer'; } };
  simRecog.onend=done; simRecog.onerror=done;
  try{ simRecog.start(); simListening=true; const mb=$('#simMic'); if(mb){ mb.classList.add('rec'); mb.innerHTML='&#9209;&#65039; Stop &amp; use it'; } }catch(e){ done(); }
}
function simFmtDur(sec){ return String(Math.floor(sec/60)).padStart(2,'0')+':'+String(sec%60).padStart(2,'0'); }
function simCallTimer(){ if(simTimerInt) clearInterval(simTimerInt); simCallStart=Date.now(); simTimerInt=setInterval(()=>{ const el=$('#simTimer'); if(!el){ clearInterval(simTimerInt); simTimerInt=null; return; } el.textContent=simFmtDur(Math.floor((Date.now()-simCallStart)/1000)); },1000); }
function simStopCall(){ try{ if(simTimerInt){ clearInterval(simTimerInt); simTimerInt=null; } }catch(e){} try{ if(window.speechSynthesis) window.speechSynthesis.cancel(); }catch(e){} try{ if(simRecog) simRecog.stop(); }catch(e){} simListening=false; }
function renderAcadSim(){ const s=$('#acadStage'); if(!s) return;
  if(csaState.simSel!=null && CSA_SIMS[csaState.simSel]){ renderSimActive(CSA_SIMS[csaState.simSel]); return; }
  simStopCall();
  const micNote = simSupportsMic()?'':' <span class="simVoiceNote">Speaking your answer needs Chrome or Edge; you can always type instead.</span>';
  s.innerHTML=`<p class="wizsub" style="margin:2px 0 10px">A live call sim: the client speaks, you answer out loud or by typing, and the client reacts to how you handle each moment. Scored every round with a full debrief. <span class="wbTag">PRACTICE &middot; VOICE</span> Everything runs locally &mdash; nothing is sent anywhere.${micNote}</p><div class="simGrid">${CSA_SIMS.map((x,i)=>`<div class="simCard"><div class="simCatTag">${esc(x.category)}</div><div class="simTitle">${esc(x.title)}</div><div class="simPersona">&#128100; ${esc(x.persona)}</div><div class="simSit">${esc(x.situation)}</div><div class="simRounds">&#128222; ${x.turns.length} rounds &middot; reacts to you</div><button class="runbtn hero simStart" data-i="${i}">&#128222; Start the call</button></div>`).join('')}</div>`;
  s.querySelectorAll('.simStart').forEach(b=>b.onclick=()=>{ startSim(+b.dataset.i); });
}
function startSim(i){ csaState.simSel=i; csaState.simTurn=0; csaState.simLog=[]; csaState.simText=''; csaState.simFb=null; csaState.simSpokenTurn=-1; simPickVoice(); simCallTimer(); renderSimActive(CSA_SIMS[i]); const st=$('#acadStage'); if(st) st.scrollIntoView({behavior:'smooth',block:'start'}); }
function renderSimActive(sim){ const s=$('#acadStage'); if(!s) return;
  if(csaState.simTurn>=sim.turns.length){ renderSimSummary(sim); return; }
  const turn=sim.turns[csaState.simTurn]; const fb=csaState.simFb; const n=sim.turns.length; const idx=csaState.simTurn;
  const line=simClientLine(sim,idx);
  const reactTag = idx>0 ? (function(){ const prev=csaState.simLog[idx-1]; const tier=(prev&&prev.tier)||'down'; return tier==='up'?'<span class="simReactTag up">eased up</span>':'<span class="simReactTag down">still guarded</span>'; })() : '';
  const thread=csaState.simLog.map((L)=>`
    <div class="simMsg client"><span class="simTag c">Client</span><p>&ldquo;${esc(L.clientLine)}&rdquo;</p></div>
    <div class="simMsg csa"><span class="simTag s">You</span><p>${esc(L.text)}</p><span class="simTurnChip band-${simBand(L.fb.overall)}">${L.fb.overall}</span></div>`).join('');
  const micBtn = simSupportsMic()?`<button class="simMicBtn" id="simMic">&#127908; Speak your answer</button>`:'';
  s.innerHTML=`<div class="wizrow" style="margin:6px 0 12px"><button class="wizghost" id="simBack">&larr; All scenarios</button><span class="simProg">Round ${idx+1} of ${n}</span></div>
    <div class="wizpanel">
    <div class="simCallHead"><div class="simAvatar">&#128100;</div><div class="simCallMeta"><div class="simCallName">${esc(sim.title)}</div><div class="simCallSub">${esc(sim.persona)}</div></div><div style="text-align:right;flex:none"><div class="simLivePill"><span class="dot"></span> Live call</div><div class="simTimer" id="simTimer">00:00</div></div><button class="simHang" id="simHang">&#9711; End</button></div>
    <p class="wizsub" style="margin:0 0 4px">${esc(sim.situation)}</p>
    <div class="simVoiceBar"><span>&#128266; Client voice</span><select id="simVoiceSel" class="simVoiceSel"></select></div>
    <div class="simThread">${thread}
      <div class="simMsg client live"><span class="simTag c">Client</span><p>&ldquo;${esc(line)}&rdquo; ${reactTag} <button class="simSpk" id="simReplay" title="Hear it again">&#128266;</button></p></div>
      ${fb?`<div class="simMsg csa"><span class="simTag s">You</span><p>${esc(csaState.simText)}</p><span class="simTurnChip band-${simBand(fb.overall)}">${fb.overall}</span></div>`:''}
    </div>
    ${fb?'':`<div class="recipeK" style="margin-top:14px">Your response</div>
    <textarea id="simInput" class="simInput" placeholder="Type your response, or tap Speak and say it out loud...">${esc(csaState.simText||'')}</textarea>
    <div class="wizrow" style="margin-top:10px">${micBtn}<button class="runbtn hero" id="simGrade">&#10022; Get AI Feedback</button><button class="wizghost" id="simReset">Clear</button></div>`}
    <div id="simFeedback">${fb?simFeedbackHTML(fb,sim,turn):''}</div></div>`;
  const back=()=>{ simStopCall(); csaState.simSel=null; csaState.simFb=null; csaState.simText=''; csaState.simTurn=0; csaState.simLog=[]; csaState.simSpokenTurn=-1; renderAcadSim(); const st=$('#acadStage'); if(st) st.scrollIntoView({behavior:'smooth',block:'start'}); };
  $('#simBack').onclick=back; const hg=$('#simHang'); if(hg) hg.onclick=back;
  const rp=$('#simReplay'); if(rp) rp.onclick=()=>simSpeak(line);
  const vsel=$('#simVoiceSel'); if(vsel){ try{ if(!simVoicePool.length) simPickVoice(); vsel.innerHTML='<option value="__auto">Auto (best per client)</option>'+simVoicePool.map((v,ix)=>'<option value="'+ix+'">'+esc(v.name)+(/en[-_]US/i.test(v.lang)?'':' ('+esc(v.lang)+')')+'</option>').join(''); vsel.value=(simVoiceOverride&&simVoicePool.indexOf(simVoiceOverride)>=0)?String(simVoicePool.indexOf(simVoiceOverride)):'__auto'; }catch(e){} vsel.onchange=()=>{ const val=vsel.value; simVoiceOverride=(val==='__auto')?null:(simVoicePool[+val]||null); try{ localStorage.setItem('csaSimVoice', simVoiceOverride?simVoiceOverride.name:'__auto'); }catch(e){} simSpeak(line); }; }
  const mb=$('#simMic'); if(mb) mb.onclick=simMicToggle;
  const ta=$('#simInput'); if(ta) ta.oninput=()=>{ csaState.simText=ta.value; };
  const rb=$('#simReset'); if(rb) rb.onclick=()=>{ csaState.simText=''; csaState.simFb=null; renderSimActive(sim); };
  const gb=$('#simGrade'); if(gb) gb.onclick=()=>{ if(simListening&&simRecog){ try{simRecog.stop();}catch(e){} } csaState.simText=(ta?ta.value:csaState.simText)||''; csaState.simFb=simEvaluate(csaState.simText,turn); renderSimActive(sim); const f=$('#simFeedback'); if(f) f.scrollIntoView({behavior:'smooth',block:'nearest'}); };
  const cb=$('#simContinue'); if(cb) cb.onclick=()=>{ const tier=simReact(csaState.simFb); csaState.simLog.push({text:csaState.simText,fb:csaState.simFb,tier:tier,clientLine:line}); csaState.simTurn++; csaState.simText=''; csaState.simFb=null; renderSimActive(sim); const st=$('#acadStage'); if(st) st.scrollIntoView({behavior:'smooth',block:'nearest'}); };
  if(csaState.simSpokenTurn!==idx){ csaState.simSpokenTurn=idx; simSpeak(line); }
}
function simEvaluate(text,turn){
  const t=(text||'').trim(), low=t.toLowerCase();
  const wc=t?t.split(/\s+/).filter(Boolean).length:0;
  const cnt=arr=>arr.reduce((n,w)=>n+(low.includes(w)?1:0),0);
  const cap=(v,m)=>Math.min(v,m);
  const rapportW=['thanks for','thank you for','good to','great to','nice to','pleasure','how are you','how have you','how you been','how you doing','how was your','how is your',"how's your",'hope you','before we dive','before we get into','get to know','tell me about you','appreciate you','glad we','looking forward','how are things','how have things'];
  const listenW=['you mentioned','you said','you were saying','sounds like','it sounds','so you','so what i','if i understand',"if i'm hearing",'it seems','earlier you','you noted','you brought up','like you said','picking up on','you told me','you shared','back to what','what i hear','circling back','you just said','to your point'];
  const empathyW=['understand','hear you','appreciate','makes sense','i get','i know','concern','feel','frustrat','valid','fair','good question','that makes','totally get','no excuse','own that','on me','right to','i can imagine','that sounds','must be',"i'm sorry",'sorry that'];
  const discoveryW=['what','how','why','tell me','walk me','help me understand','which','what would','how do','what does',"what's driving",'describe','what happened','how has','what matters','paint me','when did','how are you'];
  const valueW=['save','roi','return','value','hours','time','revenue','cost','result','outcome','impact','efficien','grow','reduce','faster','free up','cash','avoid'];
  const relW=[' we ',' our ','together','partner','your team','next step','follow up','follow-up','check in','check-in','support','walk you','alongside','with you','co-design','right-size','right size','in writing','keep an eye','stay on'];
  const hedgeW=['maybe','might','i think','sort of','kind of',' just ','hopefully','probably','i guess','possibly','not sure','i mean'];
  const q=(t.match(/\?/g)||[]).length;
  const ideal=(turn&&(turn.ideal||turn.idealPoints))||[];
  const watch=(turn&&(turn.watch||turn.watchFor))||[];
  const keyMatch=p=>{ const kw=p.toLowerCase().split(/[^a-z0-9]+/).filter(x=>x.length>4); return kw.some(k=>low.includes(k)); };
  const covList=ideal.filter(keyMatch);
  const missList=ideal.filter(p=>!keyMatch(p));
  const totalIdeal=ideal.length||1; const coverPct=covList.length/totalIdeal;
  const stage=(turn&&turn.stage)||'challenge';
  if(wc<4){ return {scores:{rapport:12,listening:12,empathy:12,discovery:12,objection:10,relationship:12},overall:12,wc,cov:0,totalIdeal,tooShort:true,covList:[],missList:ideal.slice(),traps:[],stage}; }
  const clamp=v=>Math.max(6,Math.min(98,Math.round(v)));
  const lenOk= wc<12?0: wc<28?8: wc<120?12: wc<200?6:0;
  const scores={
    rapport: clamp(26 + cap(cnt(rapportW),3)*15 + cap(cnt(empathyW),2)*5 + lenOk),
    listening: clamp(22 + cap(cnt(listenW),3)*17 + cap(q,2)*7 + lenOk),
    empathy: clamp(28 + cap(cnt(empathyW),4)*14 + (q>0?6:0)),
    discovery: clamp(22 + cap(cnt(discoveryW),4)*8 + cap(q,2)*10),
    objection: clamp(26 + Math.round(coverPct*56) + cap(cnt(valueW),4)*4),
    relationship: clamp(28 + cap(cnt(relW),3)*13 + cap(q,2)*6 + lenOk)
  };
  const W={
    rapport:    {rapport:.32,listening:.24,empathy:.20,discovery:.09,objection:0,relationship:.15},
    discovery:  {rapport:.10,listening:.24,empathy:.14,discovery:.32,objection:.05,relationship:.15},
    challenge:  {rapport:.05,listening:.14,empathy:.20,discovery:.06,objection:.35,relationship:.20},
    resolution: {rapport:.05,listening:.10,empathy:.15,discovery:.05,objection:.25,relationship:.40},
    close:      {rapport:.10,listening:.10,empathy:.12,discovery:0,objection:.08,relationship:.60}
  };
  const w=W[stage]||W.challenge;
  const overall=Math.round(scores.rapport*w.rapport+scores.listening*w.listening+scores.empathy*w.empathy+scores.discovery*w.discovery+scores.objection*w.objection+scores.relationship*w.relationship);
  const traps=[];
  if(cnt(hedgeW)>=2) traps.push('You hedged several times (&ldquo;maybe&rdquo;, &ldquo;I think&rdquo;) &mdash; speak with more conviction.');
  if(q===0 && stage!=='close') traps.push('You didn&rsquo;t ask a question &mdash; end with one to keep the dialogue open.');
  if(cnt(empathyW)===0 && (stage==='challenge'||stage==='rapport')) traps.push('Acknowledge the client&rsquo;s feeling before pivoting to your point.');
  if(stage==='rapport' && cnt(rapportW)===0 && cnt(listenW)===0) traps.push('Open with genuine warmth and pick up on what they shared before steering to business.');
  if(stage==='challenge' && cnt(valueW)===0) traps.push('Anchor on business value (time / cost / outcome), not features.');
  if((stage==='resolution'||stage==='close') && cnt(relW)===0) traps.push('Lock in a concrete next step so the relationship keeps moving.');
  watch.slice(0,2).forEach(w=>traps.push('Watch for: '+esc(w)));
  return {scores,overall,wc,cov:covList.length,totalIdeal,tooShort:false,covList,missList,traps,stage};
}
function simFeedbackHTML(fb,sim,turn){
  const band=simBand;
  if(fb.tooShort){ return `<div class="simFb"><div class="simFbHd">Add more to get scored</div><p class="wizsub">Give a fuller response (a few sentences) so MAVIS can evaluate rapport, active listening, empathy, discovery, objection-handling and relationship-building.</p></div>`; }
  const last=csaState.simTurn>=sim.turns.length-1;
  const nextHint = last?'':(simReact(fb)==='up'?' The client is warming up.':' The client is still guarded.');
  const contBtn=`<div class="wizrow" style="margin-top:14px"><button class="runbtn hero" id="simContinue">${last?'&#9989; Finish &amp; see debrief':'&#128222; Hear the client’s reply &rarr;'}</button></div>${last?'':`<div class="simVoiceNote" style="margin-top:6px">How you handled this shapes what they say next.${nextHint}</div>`}`;
  const ideal=(turn&&(turn.ideal||turn.idealPoints))||[];
  const dims=[['Rapport',fb.scores.rapport],['Active listening',fb.scores.listening],['Empathy',fb.scores.empathy],['Discovery',fb.scores.discovery],['Objection handling',fb.scores.objection],['Relationship building',fb.scores.relationship]];
  const bars=dims.map(d=>`<div class="simDim"><div class="simDimTop"><span>${d[0]}</span><b>${d[1]}</b></div><div class="simDimBar"><i class="sb-${band(d[1])}" style="width:${d[1]}%"></i></div></div>`).join('');
  const covd=fb.covList.length?`<ul>${fb.covList.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p>None yet &mdash; see the target points below.</p>';
  const miss=fb.missList.length?`<ul>${fb.missList.map(x=>`<li>${esc(x)}</li>`).join('')}</ul>`:'<p>Nicely done &mdash; you hit the key points for this moment.</p>';
  const traps=(fb.traps||[]).length?`<ul>${fb.traps.map(x=>`<li>${x}</li>`).join('')}</ul>`:'<p>No red flags &mdash; solid delivery.</p>';
  return `<div class="simFb"><div class="simFbTop"><div class="simScoreRing band-${band(fb.overall)}"><span>${fb.overall}</span></div><div><div class="simFbHd">${turn&&turn.stage?'<span class="wbTag">'+esc((turn.stage||'').toUpperCase())+'</span> ':''}This round &mdash; ${fb.overall>=80?'Strong':fb.overall>=55?'Solid, refine it':'Keep practicing'}</div><div class="wizsub" style="margin:2px 0 0">Covered ${fb.cov}/${fb.totalIdeal} ideal points this turn &middot; ${fb.wc} words &middot; <span class="wbTag">HEURISTIC</span></div></div></div>
    <div class="simDims">${bars}</div>
    <div class="delivgrid" style="margin-top:10px">
      <div class="delivblock"><div class="delivh">&#9989; You addressed</div><div class="delivb">${covd}</div></div>
      <div class="delivblock"><div class="delivh">&#127919; Add next time</div><div class="delivb">${miss}</div></div>
      <div class="delivblock"><div class="delivh">&#9888;&#65039; Coaching notes</div><div class="delivb">${traps}</div></div>
      <div class="delivblock"><div class="delivh">&#128161; What a strong answer to this hits</div><div class="delivb"><ul>${ideal.map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div></div>
    </div>${contBtn}</div>`;
}
function renderSimSummary(sim){ const s=$('#acadStage'); if(!s) return; const dur=simTimerInt?simFmtDur(Math.floor((Date.now()-simCallStart)/1000)):null; simStopCall(); const log=csaState.simLog; const n=log.length||1;
  const avg=k=>Math.round(log.reduce((a,L)=>a+(k==='overall'?L.fb.overall:L.fb.scores[k]),0)/n);
  const ov=avg('overall');
  const dims=[['Rapport','rapport'],['Active listening','listening'],['Empathy','empathy'],['Discovery','discovery'],['Objection handling','objection'],['Relationship building','relationship']];
  const bars=dims.map(d=>{const v=avg(d[1]);return `<div class="simDim"><div class="simDimTop"><span>${d[0]}</span><b>${v}</b></div><div class="simDimBar"><i class="sb-${simBand(v)}" style="width:${v}%"></i></div></div>`;}).join('');
  let cov=0,tot=0; log.forEach(L=>{cov+=L.fb.cov;tot+=L.fb.totalIdeal;});
  const eased=log.filter(L=>L.tier==='up').length;
  const trapSet=[]; log.forEach(L=>(L.fb.traps||[]).forEach(t=>{ if(t.indexOf('Watch for:')!==0 && trapSet.indexOf(t)<0) trapSet.push(t); }));
  const coaching=trapSet.length?`<ul>${trapSet.slice(0,5).map(x=>`<li>${x}</li>`).join('')}</ul>`:'<p>No recurring red flags across the call &mdash; steady, disciplined work.</p>';
  const rounds=log.map((L,i)=>`<div class="simRoundRow"><span class="simTurnChip band-${simBand(L.fb.overall)}">${L.fb.overall}</span><span>Round ${i+1}</span>${L.tier==='up'?'<span class="simReactTag up">warmed</span>':'<span class="simReactTag down">guarded</span>'}<span class="simRoundWc">${L.fb.wc} words</span></div>`).join('');
  s.innerHTML=`<div class="wizrow" style="margin:6px 0 12px"><button class="wizghost" id="simBack">&larr; All scenarios</button></div>
    <div class="wizpanel"><div class="simCatTag">${esc(sim.category)}</div><div class="wizh" style="margin:6px 0 8px">Call debrief &mdash; ${esc(sim.title)}</div>
    <div class="simFbTop"><div class="simScoreRing band-${simBand(ov)}"><span>${ov}</span></div><div><div class="simFbHd">${ov>=80?'Strong call':ov>=55?'Solid, keep refining':'Keep practicing'}</div><div class="wizsub" style="margin:2px 0 0">Averaged across ${n} rounds &middot; covered ${cov}/${tot} ideal points${dur?' &middot; call '+dur:''} &middot; client warmed on ${eased}/${n} &middot; <span class="wbTag">HEURISTIC</span></div></div></div>
    <div class="simDims">${bars}</div>
    <div class="simRounds2">${rounds}</div>
    <div class="delivgrid" style="margin-top:12px">
      <div class="delivblock"><div class="delivh">&#9888;&#65039; Patterns to work on</div><div class="delivb">${coaching}</div></div>
      <div class="delivblock"><div class="delivh">&#127919; What a strong call closed with</div><div class="delivb"><p>${esc(sim.close||'')}</p></div></div>
    </div>
    <div class="wizrow" style="margin-top:14px"><button class="runbtn hero" id="simAgain">&#128260; Practice again</button><button class="wizghost" id="simAll">All scenarios</button></div>
    </div>`;
  const back=()=>{ csaState.simSel=null; csaState.simFb=null; csaState.simText=''; csaState.simTurn=0; csaState.simLog=[]; csaState.simSpokenTurn=-1; renderAcadSim(); const st=$('#acadStage'); if(st) st.scrollIntoView({behavior:'smooth',block:'start'}); };
  $('#simBack').onclick=back; const sa=$('#simAll'); if(sa) sa.onclick=back;
  const ag=$('#simAgain'); if(ag) ag.onclick=()=>startSim(csaState.simSel);
}
// ── Interactive AI Industry Consultant ──
function scrollInd(){ const r=$('#indResults'); if(r) r.scrollIntoView({behavior:'smooth',block:'start'}); }
function indCard(ind,i){
  const ex=ind.exec||{}; const fit=ex.fit||70;
  return `<button class="indCard indOpen" data-i="${i}"><span class="indIc">&#127981;</span>
    <span class="indCardTxt"><span class="indName">${esc(ind.name)}</span><span class="indCardMeta">${esc(ex.fitLabel||'Automation fit')} · ${(ind.functions||[]).length} business functions</span></span>
    <span class="fitPill">${fit}<i>/100</i></span><span class="indArrow">&rarr;</span></button>`;
}
function indToRecipe(ind,fn,opp){
  const tools=(fn&&fn.tools)?fn.tools.slice(0,4):[];
  const near=(typeof mavisSearch==='function')?mavisSearch((opp.title||'')+' '+(opp.desc||''),1)[0]:null;
  return {kind: tools.length>=2?'integration':'capability', title:opp.title, desc:opp.desc||opp.title, problem:'', tools, cat:`${ind.name} · ${fn?fn.label:'Top automation'}`, wfId: near?near.wfId:((DATA.workflows[0]||{}).id)};
}
function indTopAutoRecipe(ind){
  const ex=ind.exec||{};
  return indToRecipe(ind,{tools:(ind.tools||[]).slice(0,4),label:'Top automation'},{title:ex.topAuto||(ind.name+' automation'),desc:ex.topAuto||''});
}
function indSortedOpps(fn){ const rk={High:0,Medium:1,Low:2}; return (fn.opportunities||[]).slice().sort((a,b)=>(rk[a.impact]??9)-(rk[b.impact]??9)); }
function indExec(ind){
  const ex=ind.exec||{}; const fit=ex.fit||70;
  return `<div class="indExec">
    <div class="indExecTop">
      <div class="fitRingWrap"><div class="fitRing" style="--p:${fit}"><span>${fit}</span></div><div class="tkRingLbl">${esc(ex.fitLabel||'Automation fit')}</div></div>
      <div class="indExecBody">
        <div class="indExecName">&#127981; ${esc(ind.name)} &mdash; Executive Summary</div>
        <p class="indExecVal">${esc(ex.value||ind.overview||'')}</p>
        <div class="delivstats" style="grid-template-columns:repeat(3,1fr)"><div><b>${esc(ex.hours||'—')}</b><span>Est. hours saved</span></div><div><b>${esc(ex.roi||'—')}</b><span>Est. ROI</span></div><div><b>${fit}/100</b><span>Automation fit</span></div></div>
      </div>
    </div>
    <div class="indTopRec"><div class="indTopRecTxt"><span class="indTopRecTag">&#9889; Top recommended automation</span><b>${esc(ex.topAuto||'')}</b></div><button class="runbtn hero indRunTop">&#10022; Run MAVIS Analysis</button></div>
    <div class="wbNote" style="margin-top:6px">Figures are estimates ($50/hr blended rate) &mdash; actual results vary by client &amp; scope.</div>
  </div>`;
}
function indFnChips(ind){
  const cur=csaState.indFn;
  return `<div class="indFnPrompt">&#128173; What are you trying to improve?</div>
    <div class="prosChips indFnChips">${(ind.functions||[]).map(f=>`<button class="prosChip${f.key===cur?' active':''}" data-fn="${esc(f.key)}">${esc(f.label)}</button>`).join('')}</div>`;
}
function indFnDetail(ind,fn){
  const opps=indSortedOpps(fn).map((o,oi)=>`<div class="oppRow"><div class="oppTop"><span class="oppTitle">${esc(o.title)}</span><span class="oppBadges"><span class="oppB impact-${(o.impact||'').toLowerCase()}">${esc(o.impact)} impact</span><span class="oppB effort-${(o.effort||'').toLowerCase()}">${esc(o.effort)} effort</span></span></div><div class="oppDesc">${esc(o.desc)}</div><button class="runbtn hero oppRun" data-o="${oi}">&#10022; Run MAVIS Analysis</button></div>`).join('');
  const agents=(fn.agents||[]).map(a=>`<div class="agentRow"><span class="agentDot">&#129302;</span><div><b>${esc(a.name)}</b> &mdash; ${esc(a.role)}</div></div>`).join('');
  const workflows=(fn.workflows||[]).map(w=>`<div class="indWf"><div class="indWfT">&#9881; ${esc(w.title)}</div><ol class="kbSteps">${(w.steps||[]).map(s=>`<li>${esc(s)}</li>`).join('')}</ol></div>`).join('');
  const tools=(fn.tools||[]).map(t=>`<span class="ecoSkill">${esc(t)}</span>`).join('');
  const im=fn.impact||{};
  const qw=(fn.quickWins||[]).map(s=>`<li>${esc(s)}</li>`).join('');
  const st=(fn.strategic||[]).map(s=>`<li>${esc(s)}</li>`).join('');
  const blocks=[
    ['&#9889; Top automation opportunities',`<div class="oppList">${opps}</div>`],
    ['&#129302; Recommended AI agents',agents||'<p>—</p>'],
    ['&#9881; Suggested workflows',workflows||'<p>—</p>'],
    ['&#128295; Required tools &amp; integrations',`<div class="tchips">${tools}</div>`],
    ['&#128176; Expected business impact',`<div class="delivstats"><div><b>${esc(im.hours||'—')}</b><span>Est. hours saved</span></div><div><b>${esc(im.cost||'—')}</b><span>Est. cost savings</span></div><div><b>${esc(im.roi||'—')}</b><span>Est. ROI</span></div></div>`],
    ['&#9193; Quick wins vs. strategic initiatives',`<div class="csa-two"><div><div class="csa-h ok">Quick wins (now)</div><ul>${qw}</ul></div><div><div class="csa-h ok">Strategic (long-term)</div><ul>${st}</ul></div></div>`],
  ];
  return `<div class="indFnPanel"><div class="wizh" style="margin:0 0 2px">${esc(fn.label)} &mdash; MAVIS recommendations</div><p class="wizsub" style="margin:0 0 8px">Click <b>Run MAVIS Analysis</b> on any opportunity for a full delivery plan &amp; implementation roadmap.</p><div class="delivgrid">${blocks.map(b=>`<div class="delivblock"><div class="delivh">${b[0]}</div><div class="delivb">${b[1]}</div></div>`).join('')}</div></div>`;
}
function indFullDetails(ind){
  const road=(ind.roadmap||[]).map(p=>`<div class="roadCol"><div class="roadH">${esc(p.phase)}<span>${esc(p.timeline)}</span></div><ul>${(p.items||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></div>`).join('');
  const tpl=(ind.templates||[]).map(t=>`<div class="tplRow"><b>${esc(t.title)}</b><div>${esc(t.desc)}</div></div>`).join('');
  const pain=(ind.painPoints||[]).map(p=>`<li>${esc(p)}</li>`).join('');
  return `<details class="csaPlaybook indFull" style="margin-top:14px"><summary>&#128218; Full industry playbook &mdash; overview, roadmap &amp; templates</summary>
    <div class="delivgrid" style="margin-top:10px">
      <div class="delivblock"><div class="delivh">&#127981; Industry overview</div><div class="delivb"><p>${esc(ind.overview||'')}</p>${pain?`<div class="recipeK" style="margin-top:8px">Common pain points</div><ul>${pain}</ul>`:''}</div></div>
      <div class="delivblock"><div class="delivh">&#128736; Implementation roadmap</div><div class="delivb"><div class="roadmapGrid">${road}</div></div></div>
      <div class="delivblock"><div class="delivh">&#129513; Reusable templates</div><div class="delivb"><div class="tplList">${tpl}</div></div></div>
    </div></details>`;
}
function renderIndustry(){
  const box=$('#indResults'), cnt=$('#indCount'), search=$('#indSearch'); if(!box) return;
  const drilled=csaState.indSel!=null && CSA_INDUSTRY[csaState.indSel];
  if(search) search.style.display=drilled?'none':'';
  if(cnt) cnt.style.display=drilled?'none':'';
  if(drilled){
    const ind=CSA_INDUSTRY[csaState.indSel];
    if(csaState.indRun&&csaState.indRun.recipe){
      const rec=csaState.indRun.recipe;
      box.innerHTML=`<div class="wizrow" style="margin:6px 0 12px"><button class="wizghost" id="indRunBack">&larr; Back to recommendations</button><button class="runbtn hero" id="indRunLive">&#10022; Run Live Analysis</button></div>${csaPlanner(rec,rec.title,csaState.indRunRel||[])}`;
      $('#indRunBack').onclick=()=>{ csaState.indRun=null; renderIndustry(); scrollInd(); };
      $('#indRunLive').onclick=()=>selectAnalysis(rec.wfId);
      box.querySelectorAll('[data-rel-open]').forEach(b=>b.onclick=()=>{ const i=+b.dataset.relOpen; const rr=(csaState.indRunRel||[])[i]; if(rr){ csaState.indRun={recipe:rr}; renderIndustry(); scrollInd(); } });
      bindCopy(); return;
    }
    let html=`<div class="wizrow" style="margin:6px 0 12px"><button class="wizghost" id="indBack">&larr; All industries</button></div>`;
    html+=indExec(ind)+indFnChips(ind);
    const fn=(ind.functions||[]).find(f=>f.key===csaState.indFn);
    html+= fn?indFnDetail(ind,fn):`<div class="indFnHint">&#128072; Pick a business function above to see MAVIS&rsquo;s targeted recommendations &mdash; opportunities, AI agents, workflows, tools, expected impact, and quick wins vs. strategic plays.</div>`;
    html+=indFullDetails(ind);
    box.innerHTML=html;
    $('#indBack').onclick=()=>{ csaState.indSel=null; csaState.indFn=null; csaState.indRun=null; renderIndustry(); scrollInd(); };
    const rt=box.querySelector('.indRunTop'); if(rt) rt.onclick=()=>{ csaState.indRunRel=null; csaState.indRun={recipe:indTopAutoRecipe(ind)}; renderIndustry(); scrollInd(); };
    box.querySelectorAll('.indFnChips .prosChip').forEach(b=>b.onclick=()=>{ csaState.indFn=b.dataset.fn; renderIndustry(); const p=$('#indResults .indFnPanel'); if(p) p.scrollIntoView({behavior:'smooth',block:'nearest'}); });
    if(fn){ const recs=indSortedOpps(fn).map(o=>indToRecipe(ind,fn,o));
      box.querySelectorAll('.oppRun').forEach(b=>b.onclick=()=>{ const oi=+b.dataset.o; csaState.indRunRel=recs; csaState.indRun={recipe:recs[oi]}; renderIndustry(); scrollInd(); }); }
    return;
  }
  const q=(csaState.indQ||'').trim().toLowerCase();
  let list=CSA_INDUSTRY.map((e,i)=>({e,i}));
  if(q){ list=list.filter(({e})=>{ const ex=e.exec||{}; const hay=(e.name+' '+e.overview+' '+(ex.topAuto||'')+' '+(ex.value||'')+' '+(e.tools||[]).join(' ')+' '+(e.functions||[]).map(f=>f.label).join(' ')+' '+(e.painPoints||[]).join(' ')).toLowerCase(); return hay.includes(q); }); }
  if(cnt) cnt.textContent=`${list.length} indust${list.length===1?'ry':'ries'}`;
  if(!list.length){ box.innerHTML=`<div class="csaResHint">No industry matches &mdash; try <b>law</b>, <b>healthcare</b>, <b>e-commerce</b>, <b>construction</b>, or <b>recruiting</b>.</div>`; return; }
  box.innerHTML=`<div class="indGrid">${list.map(({e,i})=>indCard(e,i)).join('')}</div>`;
  box.querySelectorAll('.indOpen').forEach(b=>b.onclick=()=>{ csaState.indSel=+b.dataset.i; csaState.indFn=null; csaState.indRun=null; renderIndustry(); scrollInd(); });
}
function kbCard(e,i){
  const meta={tool:['Tool How-To','🔧'],integration:['Integration','🔌'],task:['Task Execution','✅'],template:['Template','🧩'],trouble:['Troubleshooting','🛠']}[e.cat]||['Guide','📄'];
  const chips=(e.tools||[]).slice(0,4).map(t=>`<span class="ecoSkill">${esc(t)}</span>`).join('');
  return `<div class="kbCard"><div class="kbCardHd"><span class="kbBadge kb-${e.cat}">${meta[1]} ${esc(meta[0])}</span></div>
    <div class="kbTitle">${esc(e.title)}</div><div class="kbSummary">${esc(e.summary)}</div>
    ${chips?`<div class="tchips" style="margin-top:8px">${chips}</div>`:''}
    <button class="wizghost kbOpen" data-i="${i}" style="margin-top:11px">Open guide &rarr;</button></div>`;
}
function kbDetail(e){
  const meta={tool:['Tool How-To','🔧'],integration:['Integration','🔌'],task:['Task Execution','✅'],template:['Template','🧩'],trouble:['Troubleshooting','🛠']}[e.cat]||['Guide','📄'];
  const steps=(e.steps||[]).map(s=>`<li>${esc(s)}</li>`).join('');
  const tips=(e.tips||[]).map(s=>`<li>${esc(s)}</li>`).join('');
  const chips=(e.tools||[]).map(t=>`<span class="ecoSkill">${esc(t)}</span>`).join('');
  const tags=(e.tags||[]).map(t=>`<span class="kbTag">${esc(t)}</span>`).join('');
  return `<div class="wizpanel"><span class="kbBadge kb-${e.cat}">${meta[1]} ${esc(meta[0])}</span>
    <div class="wizh" style="margin:8px 0 0">${esc(e.title)}</div><p class="wizsub">${esc(e.summary)}</p>
    ${chips?`<div class="recipeK">Tools &amp; platforms</div><div class="tchips" style="margin:4px 0 12px">${chips}</div>`:''}
    <div class="delivblock"><div class="delivh">&#128736; Step-by-step</div><div class="delivb"><ol class="kbSteps">${steps}</ol></div></div>
    ${tips?`<div class="delivblock" style="margin-top:10px"><div class="delivh">&#128161; Tips &amp; gotchas</div><div class="delivb"><ul>${tips}</ul></div></div>`:''}
    ${tags?`<div class="kbTags">${tags}</div>`:''}</div>`;
}
function renderKB(){
  const box=$('#kbResults'), cnt=$('#kbCount'); if(!box) return;
  if(csaState.kbSel!=null && CSA_KB[csaState.kbSel]){
    box.innerHTML=`<div class="wizrow" style="margin:6px 0 12px"><button class="wizghost" id="kbBack">&larr; Back to guides</button></div>${kbDetail(CSA_KB[csaState.kbSel])}`;
    const bk=$('#kbBack'); if(bk) bk.onclick=()=>{ csaState.kbSel=null; renderKB(); const r=$('#kbResults'); if(r) r.scrollIntoView({behavior:'smooth',block:'nearest'}); };
    if(cnt) cnt.textContent=''; bindCopy(); return;
  }
  const q=(csaState.kbQ||'').trim().toLowerCase();
  const toks=q.split(/[^a-z0-9]+/).filter(t=>t.length>1);
  let list=CSA_KB.map((e,i)=>({e,i})).filter(({e})=>(csaState.kbCat==='all'||e.cat===csaState.kbCat));
  if(toks.length){ list=list.filter(({e})=>{ const hay=(e.title+' '+e.summary+' '+(e.tags||[]).join(' ')+' '+(e.tools||[]).join(' ')+' '+(e.steps||[]).join(' ')).toLowerCase(); return toks.every(t=>hay.includes(t)); }); }
  if(cnt) cnt.textContent=`${list.length} guide${list.length===1?'':'s'}`;
  if(!list.length){ box.innerHTML=`<div class="csaResHint">No guides match &mdash; try a tool (<b>Slack</b>), a topic (<b>OAuth</b>, <b>webhook</b>), or a task (<b>onboarding</b>, <b>reporting</b>).</div>`; return; }
  box.innerHTML=`<div class="kbGrid">${list.map(({e,i})=>kbCard(e,i)).join('')}</div>`;
  box.querySelectorAll('.kbOpen').forEach(b=>b.onclick=()=>{ csaState.kbSel=+b.dataset.i; renderKB(); const r=$('#kbResults'); if(r) r.scrollIntoView({behavior:'smooth',block:'nearest'}); });
}
// ---- workflow-recipe discovery engine ----
function hashStr(s){ let h=0; for(let i=0;i<s.length;i++) h=(h*31+s.charCodeAt(i))>>>0; return h; }
function sentence(s){ s=String(s).trim(); return s.charAt(0).toUpperCase()+s.slice(1); }
function recipeMetrics(r){ const h=hashStr(r.title+r.tools.join()); const complexity=['Low','Medium','Medium','High'][h%4]; const timeSaved=2+(h>>3)%9; const effort=complexity==='Low'?'~1 hr setup':complexity==='High'?'~1 day setup':'~2-3 hrs setup'; return {complexity,timeSaved,effort}; }
function intRecipe(i){ const near=rankCaps(i.desc+' '+i.tools.join(' '),1)[0]; return {kind:'integration',tools:i.tools.slice(),desc:i.desc,cat:i.cat,title:sentence(i.desc),wfId:near?near.w.id:DATA.workflows[0].id}; }
function capRecipe(w){ return {kind:'capability',tools:(w.integrations||[]).slice(),desc:w.autoRec||w.autoType,cat:w.dept,title:w.name,wfId:w.id}; }
function buildRecipes(query){ return mavisSearch(query,10); }
function intsByTool(name){ const n=name.toLowerCase(); return (DATA.catalog.integrations||[]).filter(i=>i.tools.some(t=>t.toLowerCase()===n)); }
// ── Industry discovery: curated, MAVIS-executable automations per business vertical ──
// Each play: [business process, what it does, problem it solves, MAVIS capability id, tools]
