function renderPBResults(){
  const box=$('#pbResults'), cnt=$('#pbCount'); if(!box) return;
  const q=(techWiz.pbQ||'').trim().toLowerCase();
  // detail views (a card was opened)
  if(techWiz.pbToolSel!=null && CSA_TOOLS[techWiz.pbToolSel]){
    box.innerHTML=`<div class="wizrow" style="margin:6px 0 12px"><button class="wizghost" id="pbBack">&larr; Back to guides</button></div>${toolDetail(CSA_TOOLS[techWiz.pbToolSel])}`;
    const bk=$('#pbBack'); if(bk) bk.onclick=()=>{ techWiz.pbToolSel=null; renderPBResults(); }; if(cnt) cnt.textContent=''; bindCopy(); return;
  }
  if(techWiz.pbSel!=null && CSA_KB[techWiz.pbSel]){
    box.innerHTML=`<div class="wizrow" style="margin:6px 0 12px"><button class="wizghost" id="pbBack2">&larr; Back to guides</button></div>${kbDetail(CSA_KB[techWiz.pbSel])}`;
    const bk=$('#pbBack2'); if(bk) bk.onclick=()=>{ techWiz.pbSel=null; renderPBResults(); }; if(cnt) cnt.textContent=''; bindCopy(); return;
  }
  // build unified list for the active category (All merges tools + tasks + templates)
  const toks=q.split(/[^a-z0-9]+/).filter(t=>t.length>1);
  const toolItems=()=>{ let l=CSA_TOOLS.map((t,i)=>({kind:'tool',i,t})); if(toks.length) l=l.filter(({t})=>{ const hay=(t.name+' '+t.category+' '+(t.features||[]).join(' ')+' '+(t.useCases||[]).join(' ')+' '+(t.workflows||[]).join(' ')).toLowerCase(); return toks.every(x=>hay.includes(x)); }); return l; };
  const kbItems=(cat)=>kbFilter([cat],q).map(({e,i})=>({kind:'kb',i,e}));
  let items;
  if(techWiz.pbCat==='tool') items=toolItems();
  else if(techWiz.pbCat==='task') items=kbItems('task');
  else if(techWiz.pbCat==='template') items=kbItems('template');
  else items=[...toolItems(),...kbItems('task'),...kbItems('template')];
  if(cnt) cnt.textContent=`${items.length} guide${items.length===1?'':'s'}`;
  box.innerHTML=items.length?`<div class="pbGrid">${items.map(pbCard).join('')}</div>`:`<div class="csaResHint">No guides match &mdash; try <b>Salesforce</b>, <b>OAuth</b>, <b>onboarding</b>, or a <b>CRM template</b>.</div>`;
  box.querySelectorAll('.pbCard').forEach(b=>b.onclick=()=>{ if(b.dataset.kind==='tool'){ techWiz.pbToolSel=+b.dataset.i; } else { techWiz.pbSel=+b.dataset.i; } renderPBResults(); const r=$('#pbResults'); if(r) r.scrollIntoView({behavior:'smooth',block:'nearest'}); });
}
