var LB_KEY = "mavis_links_bank_v2";
var lbState = { q:"", category:"", type:"", tool:"", sort:"recent", page:1, per:8, admin:false, editId:null };
function lbUid(){ return "l"+Math.random().toString(36).slice(2,9); }
function lbSeed(){ return LINKS_BANK_DEFAULT.map(function(l,i){ return Object.assign({id:"seed"+i}, l); }); }
function lbGet(){ try{ var r=localStorage.getItem(LB_KEY); if(r){ var a=JSON.parse(r); if(Array.isArray(a)&&a.length) return a; } }catch(e){} return lbSeed(); }
function lbSave(list){ try{ localStorage.setItem(LB_KEY, JSON.stringify(list)); }catch(e){} }
var LB_ICON={"Google Sheet":"📊","Google Slides":"📽️","Google Doc":"📄","PDF":"📕","Drive folder":"📁","Zoom link":"🎥","Calendar link":"📅","Web app":"🧩","Website":"🌐","Image":"🖼️","Video":"🎬"};
var LB_TCOL={"Google Sheet":"g","Google Slides":"a","Google Doc":"b","PDF":"r","Drive folder":"n","Zoom link":"b","Calendar link":"p","Web app":"p","Website":"t","Image":"k","Video":"k"};
function lbIcon(t){ return LB_ICON[t]||"🔗"; }
function lbBadge(t){ return '<span class="lbBadge lbb-'+(LB_TCOL[t]||"n")+'">'+esc(t)+'</span>'; }
function lbDate(s){ if(!s) return "—"; var d=new Date(s+"T00:00:00"); if(isNaN(d)) return esc(s); return d.toLocaleDateString("en-US",{month:"short",day:"numeric",year:"numeric"}); }
function lbUniq(list,key){ var s=[]; list.forEach(function(l){ var v=l[key]; if(v&&s.indexOf(v)<0) s.push(v); }); s.sort(); return s; }
function lbMatch(l){
  var term=lbState.q.trim().toLowerCase();
  var hay=(l.name+" "+l.desc+" "+l.tool+" "+l.category+" "+l.type).toLowerCase();
  if(term && hay.indexOf(term)<0) return false;
  if(lbState.category && l.category!==lbState.category) return false;
  if(lbState.type && l.type!==lbState.type) return false;
  if(lbState.tool && l.tool!==lbState.tool) return false;
  return true;
}
function lbSort(a){
  a=a.slice();
  if(lbState.sort==="az") a.sort(function(x,y){return x.name.localeCompare(y.name);});
  else if(lbState.sort==="za") a.sort(function(x,y){return y.name.localeCompare(x.name);});
  else if(lbState.sort==="cat") a.sort(function(x,y){return (x.category||"").localeCompare(y.category||"")||x.name.localeCompare(y.name);});
  else a.sort(function(x,y){return String(y.updated||"").localeCompare(String(x.updated||""));});
  return a;
}
function viewLinks(){
  var links=lbGet();
  var cats=lbUniq(links,"category").length, tools=lbUniq(links,"tool").length;
  return `<section class="card">
    ${sectionHero('&#128279;','Links Bank','Find, filter, and open the resources CSAs use most &mdash; search by name, tool, or keyword and open in a new tab without leaving the hub.',[[links.length,'Links'],[cats,'Categories'],[tools,'Tools']])}
    <div class="lbTop">
      <button class="lbBtn primary" id="lbAdd">+ Add link</button>
      <button class="lbBtn ghost" id="lbAdmin">Admin View</button>
      <button class="lbBtn ghost lbAdminOnly" id="lbExport">Export</button>
      <button class="lbBtn ghost lbAdminOnly" id="lbImport">Import</button>
    </div>
    <div class="lbAdminBanner lbAdminOnly">Admin View is on &mdash; add, edit, delete, and export the library. CSAs see a clean, link-only view.</div>
    <div class="lbToolbar">
      <div class="lbSearch"><span class="lbSi">&#128269;</span><input id="lbQ" placeholder="Search by name, keyword, or tool..." autocomplete="off"></div>
      <div class="lbFilts">
        <select class="lbSel" id="lbCat"></select>
        <select class="lbSel" id="lbType"></select>
        <select class="lbSel" id="lbTool"></select>
        <button class="lbClear" id="lbClear">Clear all</button>
      </div>
    </div>
    <div id="lbQaSec">
      <div class="lbSecH"><span class="lbSecT">Quick Access</span><span class="lbSecC">Frequently used resources</span></div>
      <div class="lbQa" id="lbQa"></div>
    </div>
    <div class="lbSecH lbAllH"><span class="lbSecT">All Resources</span><span class="lbSecC" id="lbAllCap"></span>
      <select class="lbSel lbSort" id="lbSort">
        <option value="recent">Sort by: Recently Updated</option>
        <option value="az">Sort by: Name (A–Z)</option>
        <option value="za">Sort by: Name (Z–A)</option>
        <option value="cat">Sort by: Category</option>
      </select></div>
    <div class="lbTableWrap">
      <table class="lbTable"><thead><tr>
        <th>Resource Name</th><th class="lbHcat">Category</th><th>Type</th><th class="lbHupd">Last Updated</th><th style="text-align:right">Action</th>
      </tr></thead><tbody id="lbRows"></tbody></table>
      <div class="lbPfoot"><div class="lbPinfo" id="lbPinfo"></div><div class="lbPager" id="lbPager"></div></div>
    </div>
  </section>`;
}
function lbFillFilters(links){
  function opts(sel,vals,label){ if(!sel) return; var cur=sel.value;
    sel.innerHTML='<option value="">'+label+'</option>'+vals.map(function(v){return '<option value="'+esc(v)+'">'+esc(v)+'</option>';}).join("");
    sel.value=cur; }
  opts($('#lbCat'),lbUniq(links,"category"),"All Categories");
  opts($('#lbType'),lbUniq(links,"type"),"All Types");
  opts($('#lbTool'),lbUniq(links,"tool"),"All Tools");
}
function lbRenderQuick(links){
  var qa=links.filter(function(l){return l.quick;});
  var sec=$('#lbQaSec'), g=$('#lbQa'); if(!g) return;
  if(sec) sec.style.display=qa.length?"":"none";
  g.innerHTML=qa.map(function(l){
    return '<div class="lbQaCard" data-open="'+esc(l.url)+'"><div class="lbIco">'+lbIcon(l.type)+'</div>'+
      '<div class="lbQaM"><div class="lbQaN">'+esc(l.name)+'</div><div class="lbQaT">'+esc(l.tool)+'</div></div></div>';
  }).join("");
  g.querySelectorAll("[data-open]").forEach(function(c){ c.onclick=function(){ openExternal(c.getAttribute("data-open")); }; });
}
function lbRenderTable(links){
  var all=lbSort(links.filter(lbMatch));
  var total=all.length, pages=Math.max(1,Math.ceil(total/lbState.per));
  if(lbState.page>pages) lbState.page=pages;
  var start=(lbState.page-1)*lbState.per, slice=all.slice(start,start+lbState.per);
  var tb=$('#lbRows'); if(!tb) return;
  if(!total){ tb.innerHTML='<tr><td colspan="5"><div class="lbEmpty">No resources match. Try another keyword or clear the filters.</div></td></tr>'; }
  else tb.innerHTML=slice.map(function(l){
    var tag=l.badge==="new"?'<span class="lbTag lbTn">New</span>':l.badge==="upd"?'<span class="lbTag lbTu">Updated</span>':"";
    return '<tr>'+
      '<td><div class="lbRn"><div class="lbIco">'+lbIcon(l.type)+'</div><div class="lbRm">'+
        '<div class="lbRnN">'+esc(l.name)+' '+tag+'</div><div class="lbRnD">'+esc(l.desc)+'</div></div></div></td>'+
      '<td class="lbTcat">'+esc(l.category||"—")+'</td>'+
      '<td>'+lbBadge(l.type)+'</td>'+
      '<td class="lbTupd">'+lbDate(l.updated)+'</td>'+
      '<td><div class="lbRowAct">'+
        '<button class="lbOpen" data-open="'+esc(l.url)+'">Open &#8599;</button>'+
        '<div class="lbKwrap lbAdminOnly"><button class="lbKebab" data-menu="'+l.id+'">&#8943;</button></div>'+
      '</div></td></tr>';
  }).join("");
  tb.querySelectorAll("[data-open]").forEach(function(b){ b.onclick=function(){ openExternal(b.getAttribute("data-open")); }; });
  tb.querySelectorAll("[data-menu]").forEach(function(b){ b.onclick=function(e){ e.stopPropagation(); lbToggleMenu(b); }; });
  var cap=$('#lbAllCap'); if(cap) cap.textContent=total+" resource"+(total===1?"":"s");
  var endN=Math.min(start+lbState.per,total);
  var pin=$('#lbPinfo'); if(pin) pin.textContent=total?("Showing "+(start+1)+" to "+endN+" of "+total+" resources"):"No resources";
  lbRenderPager(pages);
}
function lbRenderPager(pages){
  var p=$('#lbPager'); if(!p) return;
  if(pages<=1){ p.innerHTML=""; return; }
  var h='<button class="lbPg" '+(lbState.page===1?"disabled":"")+' data-pg="'+(lbState.page-1)+'">&#8249;</button>';
  for(var i=1;i<=pages;i++) h+='<button class="lbPg'+(i===lbState.page?" act":"")+'" data-pg="'+i+'">'+i+'</button>';
  h+='<button class="lbPg" '+(lbState.page===pages?"disabled":"")+' data-pg="'+(lbState.page+1)+'">&#8250;</button>';
  p.innerHTML=h;
  p.querySelectorAll("[data-pg]").forEach(function(b){ b.onclick=function(){ var n=+b.getAttribute("data-pg"); if(n>=1&&n<=pages){ lbState.page=n; lbRenderTable(lbGet()); } }; });
}
function lbToggleMenu(btn){
  lbCloseMenus();
  var id=btn.getAttribute("data-menu");
  var m=document.createElement("div"); m.className="lbRowMenu";
  m.innerHTML='<button data-edit="'+id+'">Edit</button><button class="del" data-del="'+id+'">Delete</button>';
  btn.parentElement.appendChild(m);
  m.querySelector("[data-edit]").onclick=function(){ lbCloseMenus(); lbOpenModal(id); };
  m.querySelector("[data-del]").onclick=function(){ lbCloseMenus(); lbDelete(id); };
}
function lbCloseMenus(){ document.querySelectorAll(".lbRowMenu").forEach(function(m){ m.remove(); }); }
function lbApply(){
  var links=lbGet();
  lbFillFilters(links); lbRenderQuick(links); lbRenderTable(links);
}
function lbEnsureModal(){
  if(document.getElementById("lbOv")) return;
  var ov=document.createElement("div"); ov.id="lbOv"; ov.className="lbOv";
  ov.innerHTML='<div class="lbModal"><div class="lbMh"><span id="lbMTitle">Add a link</span><button class="lbMx" id="lbMClose">&times;</button></div>'+
    '<div class="lbMb">'+
    '<label class="wide">Resource name<input id="lbmName" placeholder="CSA Schedule Dashboard"></label>'+
    '<label class="wide">URL<input id="lbmUrl" placeholder="https://..."></label>'+
    '<label>Category<input id="lbmCat" placeholder="Onboarding"></label>'+
    '<label>Type<input id="lbmType" placeholder="Google Sheet"></label>'+
    '<label>Tool / System<input id="lbmTool" placeholder="Google Sheets"></label>'+
    '<label>Snapshot image URL<input id="lbmImg" placeholder="optional"></label>'+
    '<label class="wide">Description<input id="lbmDesc" placeholder="What this resource is used for"></label>'+
    '<label class="row2"><input type="checkbox" id="lbmQuick"> Pin to Quick Access</label>'+
    '</div><div class="lbMf"><button class="lbBtn ghost" id="lbmCancel">Cancel</button><button class="lbBtn primary" id="lbmSave">Save link</button></div></div>';
  document.body.appendChild(ov);
  ov.addEventListener("click",function(e){ if(e.target===ov) lbCloseModal(); });
  $('#lbMClose').onclick=lbCloseModal; $('#lbmCancel').onclick=lbCloseModal; $('#lbmSave').onclick=lbSaveModal;
}
function lbOpenModal(id){
  lbEnsureModal();
  lbState.editId=id||null;
  var l=id?lbGet().filter(function(x){return x.id===id;})[0]:{name:"",url:"",category:"",type:"",tool:"",img:"",desc:"",quick:false};
  $('#lbMTitle').textContent=id?"Edit link":"Add a link";
  $('#lbmName').value=l.name||""; $('#lbmUrl').value=l.url||""; $('#lbmCat').value=l.category||"";
  $('#lbmType').value=l.type||""; $('#lbmTool').value=l.tool||""; $('#lbmImg').value=l.img||"";
  $('#lbmDesc').value=l.desc||""; $('#lbmQuick').checked=!!l.quick;
  $('#lbOv').classList.add("show");
}
function lbCloseModal(){ var o=$('#lbOv'); if(o) o.classList.remove("show"); lbState.editId=null; }
function lbSaveModal(){
  var name=$('#lbmName').value.trim(), url=$('#lbmUrl').value.trim();
  if(!name||!url){ alert("Name and URL are both required."); return; }
  var today=new Date().toISOString().slice(0,10);
  var rec={ name:name, url:url, category:$('#lbmCat').value.trim(), type:$('#lbmType').value.trim()||"Website",
    tool:$('#lbmTool').value.trim(), img:$('#lbmImg').value.trim(), desc:$('#lbmDesc').value.trim(),
    quick:$('#lbmQuick').checked, updated:today, badge:"" };
  var list=lbGet();
  if(lbState.editId){ var i=list.findIndex(function(x){return x.id===lbState.editId;}); if(i>=0){ rec.id=lbState.editId; rec.badge=list[i].badge; list[i]=rec; } }
  else { rec.id=lbUid(); rec.badge="new"; list.push(rec); }
  lbSave(list); lbCloseModal(); lbApply();
}
function lbDelete(id){ if(!confirm("Delete this link?")) return; lbSave(lbGet().filter(function(x){return x.id!==id;})); lbApply(); }
function lbExport(){
  var blob=new Blob([JSON.stringify(lbGet(),null,2)],{type:"application/json"}), url=URL.createObjectURL(blob);
  var a=document.createElement("a"); a.href=url; a.download="links-bank.json"; document.body.appendChild(a); a.click(); a.remove();
  setTimeout(function(){ URL.revokeObjectURL(url); },1500);
}
function lbImport(){
  var inp=document.createElement("input"); inp.type="file"; inp.accept="application/json,.json";
  inp.onchange=function(){ var f=inp.files&&inp.files[0]; if(!f) return; var r=new FileReader();
    r.onload=function(){ try{ var a=JSON.parse(r.result); if(!Array.isArray(a)) throw 0;
      var clean=a.filter(function(x){return x&&x.name&&x.url;}).map(function(x){return {
        id:x.id||lbUid(), name:String(x.name), url:String(x.url), category:String(x.category||""),
        type:String(x.type||"Website"), tool:String(x.tool||""), img:String(x.img||""), desc:String(x.desc||""),
        quick:!!x.quick, updated:String(x.updated||""), badge:String(x.badge||"") };});
      if(!clean.length){ alert("No valid links in that file."); return; }
      lbSave(clean); lbApply();
    }catch(e){ alert("That file is not a valid Links Bank export."); } };
    r.readAsText(f); };
  inp.click();
}
